/**
 * RN.1.5 direct-Core transformation oracle fixture integrity.
 *
 * The oracle itself is generated by `tools/oracle` against Cribra Core. These
 * checks pin the synthetic fixture's structural invariants without loading the
 * native module; exact scan/output parity is exercised on the simulator and
 * emulator harness.
 */

jest.mock('../../src/NativeCribraReactNative', () => {
  throw new Error('transform oracle tests must not load the native module');
});

interface TransformCase {
  readonly name: string;
  readonly source: string;
  readonly request: { readonly kind: string };
}

interface OracleCase {
  readonly name: string;
  readonly output?: string;
  readonly error?: string;
  readonly scan?: {
    readonly sourceBytes: number;
    readonly findingCount: number;
    readonly candidateCount: number;
    readonly findings: readonly { readonly span: { start: number; end: number } }[];
    readonly candidates: readonly { readonly span: { start: number; end: number } }[];
  };
}

const cases = require('../src/fixtures/rn15-transform-cases.json') as TransformCase[];
const oracle = require('../src/fixtures/rn15-transform-oracle.json') as {
  cases: readonly OracleCase[];
};

const caseByName = new Map(cases.map((entry) => [entry.name, entry]));
const oracleByName = new Map(oracle.cases.map((entry) => [entry.name, entry]));

/** Independent UTF-8 length so the oracle is not trusted for source size. */
function utf8ByteLength(value: string): number {
  let bytes = 0;
  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (code < 0x80) {
      bytes += 1;
    } else if (code < 0x800) {
      bytes += 2;
    } else if (
      code >= 0xd800 &&
      code <= 0xdbff &&
      index + 1 < value.length &&
      value.charCodeAt(index + 1) >= 0xdc00 &&
      value.charCodeAt(index + 1) <= 0xdfff
    ) {
      bytes += 4;
      index += 1;
    } else {
      bytes += 3;
    }
  }
  return bytes;
}

describe('direct-Core transform oracle', () => {
  it('has one oracle case per fixture case with unique names', () => {
    expect(oracle.cases).toHaveLength(cases.length);
    expect(caseByName.size).toBe(cases.length);
    expect(oracleByName.size).toBe(oracle.cases.length);
  });

  it('uses only the four documented transformation kinds', () => {
    for (const entry of cases) {
      expect(['redact', 'template', 'pseudonymize', 'synthesize']).toContain(
        entry.request.kind,
      );
    }
  });

  for (const entry of oracle.cases) {
    const fixture = caseByName.get(entry.name);
    if (fixture === undefined) {
      throw new Error(`oracle case ${entry.name} has no fixture`);
    }

    if (entry.error !== undefined) {
      it(`${entry.name} records a known transform error`, () => {
        expect([
          'transform_invalid_span',
          'transform_invalid_utf8_boundary',
          'transform_overlapping_spans',
          'transform_unknown',
        ]).toContain(entry.error);
        expect(entry.output).toBeUndefined();
      });
      continue;
    }

    it(`${entry.name} has a coherent scan and output`, () => {
      expect(typeof entry.output).toBe('string');
      expect(entry.scan).toBeDefined();
      const scan = entry.scan as NonNullable<OracleCase['scan']>;
      expect(scan.sourceBytes).toBe(utf8ByteLength(fixture.source));
      expect(scan.findings).toHaveLength(scan.findingCount);
      expect(scan.candidates).toHaveLength(scan.candidateCount);
      for (const item of [...scan.findings, ...scan.candidates]) {
        expect(item.span.start).toBeGreaterThanOrEqual(0);
        expect(item.span.end).toBeGreaterThanOrEqual(item.span.start);
        expect(item.span.end).toBeLessThanOrEqual(scan.sourceBytes);
      }
    });
  }

  it('never transforms review candidates', () => {
    for (const name of [
      'redact_candidate_only',
      'template_candidate_only',
      'pseudonymize_candidate_only',
      'synthesize_candidate_only',
    ]) {
      const entry = oracleByName.get(name);
      const fixture = caseByName.get(name);
      expect(entry?.scan?.candidateCount).toBe(1);
      expect(entry?.scan?.findingCount).toBe(0);
      expect(entry?.output).toBe(fixture?.source);
    }
  });

  it('pins deterministic keyed repeats and digest clamping', () => {
    expect(oracleByName.get('pseudonymize_default')?.output).toBe(
      oracleByName.get('pseudonymize_repeat')?.output,
    );
    expect(oracleByName.get('synthesize_default')?.output).toBe(
      oracleByName.get('synthesize_repeat')?.output,
    );
    // Core clamps 1 to 8 digest bytes (16 hex chars) and 64 to 32 bytes (64
    // hex chars) behind the default 14-character prefix.
    expect(oracleByName.get('pseudonymize_digest_clamped_low')?.output).toHaveLength(
      13 + 14 + 16 + 1,
    );
    expect(oracleByName.get('pseudonymize_digest_clamped_high')?.output).toHaveLength(
      13 + 14 + 64 + 1,
    );
  });

  it('rejects overlapping findings only in strict modes', () => {
    expect(oracleByName.get('redact_overlap_merged')?.error).toBeUndefined();
    for (const name of [
      'template_overlap_error',
      'pseudonymize_overlap_error',
      'synthesize_overlap_error',
    ]) {
      expect(oracleByName.get(name)?.error).toBe('transform_overlapping_spans');
    }
  });
});
